// Gmail -> common shape
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const sender = ((j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || '').toLowerCase().trim();
  let text = j.text || (j.html || '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, ' ');
  text = text.split(/\r?\nOn .{5,120} wrote:/)[0].split(/\r?\n-- ?\r?\n/)[0]
    .replace(/^>.*$/gm, '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
  if (!sender || !text) continue;
  out.push({ json: { query: {
    channel: 'email', sender, subject: j.subject || null, text,
    external_id: String(j.id), received_at: j.date ? new Date(j.date).toISOString() : null
  }}});
}
return out;

// Web form webhook -> common shape
// Expected body: { email, subject, message }
const b = $input.first().json.body || $input.first().json;
const sender = String(b.email || '').toLowerCase().trim();
const text = String(b.message || b.text || '').trim();
if (!sender || !text) throw new Error('email and message are required');
return [{ json: { query: {
  channel: 'web_form', sender, subject: b.subject || null, text,
  external_id: null, received_at: new Date().toISOString()
}}}];

// Fetch departments + courses (public endpoints) and build the Gemini request
const BACKEND = 'https://YOUR-BACKEND-URL';   // <- same URL as in the last node
const departments = await this.helpers.httpRequest({ method: 'GET', url: BACKEND + '/api/v1/departments', json: true });
const courses = await this.helpers.httpRequest({ method: 'GET', url: BACKEND + '/api/v1/courses', json: true });

const deptLines = departments.map(d => `- dept_id ${d.id}: ${d.name} (${d.code})`).join('\n');
const courseLines = courses.map(c => `- course_id ${c.id}: ${c.code} ${c.name} (dept_id ${c.dept_id})`).join('\n');
const ctx = { dept_ids: departments.map(d => d.id), courses: Object.fromEntries(courses.map(c => [c.id, c.dept_id])) };

return $input.all().map(item => {
  const q = item.json.query;
  const prompt = `You are the query router of a university helpdesk. Decide which department and (if any) course this student message belongs to.

DEPARTMENTS:
${deptLines}

COURSES:
${courseLines}

RULES:
- dept_id MUST be one of the listed departments, or null if you really cannot tell.
- course_id MUST be one of the listed courses and belong to the chosen department. Use null if no course is clearly meant.
- priority: low, medium, high or urgent (urgent = deadline/exam within 48h or a serious problem).
- confidence: number 0 to 1 (how sure you are about dept_id).
- reasoning: one short sentence.
- draft_reply: a short, polite acknowledgement reply to the student (max 3 sentences), in the same language as the message. Do not promise outcomes.

Return ONLY JSON: {"dept_id": number|null, "course_id": number|null, "priority": "low|medium|high|urgent", "confidence": number, "reasoning": string, "draft_reply": string}

STUDENT MESSAGE
Subject: ${q.subject || '(none)'}
${q.text.slice(0, 4000)}`;
  return { json: {
    query: q,
    ctx,
    gemini_body: { contents: [{ parts: [{ text: prompt }] }],
                   generationConfig: { responseMimeType: 'application/json', temperature: 0.1 } }
  }};
});

// Combine query + Gemini answer. If Gemini failed, send the query without AI fields
// (the backend then falls back to its keyword rules).
const src = $('Build AI Request').all();
return $input.all().map((item, i) => {
  const { query, ctx } = src[i].json;
  const payload = { ...query };
  try {
    const raw = item.json.candidates[0].content.parts[0].text;
    const ai = JSON.parse(raw.replace(/^```json\s*|```$/g, ''));
    const deptOk = Number.isInteger(ai.dept_id) && ctx.dept_ids.includes(ai.dept_id);
    if (deptOk) {
      payload.dept_id = ai.dept_id;
      if (Number.isInteger(ai.course_id) && ctx.courses[ai.course_id] === ai.dept_id) payload.course_id = ai.course_id;
      if (['low', 'medium', 'high', 'urgent'].includes(ai.priority)) payload.priority = ai.priority;
      const conf = Number(ai.confidence);
      payload.confidence = Number.isFinite(conf) ? Math.max(0, Math.min(1, conf)) : 0.5;
      if (ai.reasoning) payload.ai_reasoning = String(ai.reasoning).slice(0, 300);
    }
    if (ai.draft_reply) payload.ai_draft = String(ai.draft_reply).slice(0, 1500);
  } catch (e) { /* Gemini failed or returned bad JSON -> keyword fallback in backend */ }
  return { json: payload };
});
